package com.clavis.reader;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
/** RSS shelves use the same artwork-and-copy rows as the audio shelf. */
final class FeedScreens {

 static ImageButton toolbarIcon(MainActivity a,int icon,String label,Runnable action){ImageButton button=UiStyle.icon(a,icon,label,action,44);if(icon==R.drawable.ic_toolbar_more)button.setBackgroundColor(Color.TRANSPARENT);else button.setBackground(a.bg(AppTheme.surface,12));button.setPadding(a.dp(10),a.dp(10),a.dp(10),a.dp(10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(44),a.dp(44));p.leftMargin=a.dp(4);button.setLayoutParams(p);return button;}
 static int contentIndex(MainActivity a){for(int n=0;n<a.root.getChildCount();n++){android.view.ViewGroup.LayoutParams p=a.root.getChildAt(n).getLayoutParams();if(p instanceof LinearLayout.LayoutParams&&((LinearLayout.LayoutParams)p).weight>0)return n;}return 1;}
 static void goToTop(MainActivity a){ScrollChrome.reveal(a);View content=ScrollChrome.scroll(a.root);if(content instanceof androidx.recyclerview.widget.RecyclerView){androidx.recyclerview.widget.RecyclerView list=(androidx.recyclerview.widget.RecyclerView)content;list.setPadding(list.getPaddingLeft(),a.dp(10),list.getPaddingRight(),list.getPaddingBottom());androidx.recyclerview.widget.LinearSmoothScroller motion=new androidx.recyclerview.widget.LinearSmoothScroller(a){@Override protected int getVerticalSnapPreference(){return SNAP_TO_START;}@Override protected void onStop(){super.onStop();list.post(()->{if(list.getLayoutManager() instanceof androidx.recyclerview.widget.LinearLayoutManager)((androidx.recyclerview.widget.LinearLayoutManager)list.getLayoutManager()).scrollToPositionWithOffset(0,0);});}};motion.setTargetPosition(0);if(list.getLayoutManager()!=null)list.getLayoutManager().startSmoothScroll(motion);}else if(content instanceof ScrollView)((ScrollView)content).smoothScrollTo(0,0);}
 static void refreshAll(MainActivity a,String kind){refreshAll(a,kind,a.feedSources);}
 static void refreshAll(MainActivity a,String kind,boolean sources){ArrayList<FeedStore.Feed> selected=new ArrayList<>();for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals(kind))selected.add(feed);refresh(a,kind,selected,sources);}
 static String plain(String html){return Html.fromHtml(html,Html.FROM_HTML_MODE_LEGACY).toString().trim();}
 static void tabs(MainActivity a,String kind,boolean sources){tabs(a,kind,sources,false);}
 static void tabs(MainActivity a,String kind,boolean sources,boolean browse){a.feedSources=sources;
  LinearLayout row=a.row();
  String[] labels=new String[]{"Popular","My list"};for(int n=0;n<labels.length;n++){final boolean target=n==1,targetBrowse=n==2;TextView tab=a.button(labels[n],()->{if(targetBrowse)PodcastDirectory.show(a);else switchTab(a,kind,target);});UiStyle.compactControl(a,tab);boolean selected=browse?targetBrowse:!targetBrowse&&target==sources;tab.setSelected(selected);tab.setContentDescription(labels[n]+(selected?", selected tab":", tab"));tab.setTextColor(selected?MainActivity.INK:MainActivity.MUTED);android.graphics.drawable.GradientDrawable background=UiStyle.surface(a,kind,12);background.setColor(selected?AppTheme.raised:AppTheme.surface);background.setStroke(a.dp(1),selected?AppTheme.accent:AppTheme.line);tab.setBackground(background);LinearLayout.LayoutParams tabParams=new LinearLayout.LayoutParams(0,a.dp(44),1);tabParams.leftMargin=a.dp(3);tabParams.rightMargin=a.dp(3);row.addView(tab,tabParams);}
  a.bar.removeViewAt(1);a.bar.addView(row,1,new LinearLayout.LayoutParams(0,-1,1));FeedTopics.tags(a,kind,sources);
 }
 static final java.util.concurrent.ExecutorService loader=java.util.concurrent.Executors.newSingleThreadExecutor();
 static void popular(MainActivity a,String kind){show(a,kind,false);}
 static void show(MainActivity a,String kind){show(a,kind,false);}
 static void switchTab(MainActivity a,String kind,boolean sources){if(a.navigation!=null)a.navigation.feedTabMotion=true;try{if(a.navigation!=null&&a.navigation.showFeed(kind,sources))return;show(a,kind,sources,true);}finally{if(a.navigation!=null)a.navigation.feedTabMotion=false;}}
 static void show(MainActivity a,String kind,boolean sources){show(a,kind,sources,false);}
 static void show(MainActivity a,String kind,boolean sources,boolean switching){
  if(!switching&&a.navigation!=null)a.navigation.invalidateFeed(kind);
  a.screen=kind;a.feedSources=sources;a.shell(FeedCatalog.label(kind));a.bar.removeViewAt(2);
  a.bar.addView(toolbarIcon(a,R.drawable.ic_toolbar_more,"Feed actions",()->new AppDialog.Builder(a).setTitle("Feed actions").setItems(new String[]{"Sort by",kind.equals("Podcasts")?"Browse podcasts":"Browse sources","Refresh all sources"},(d,n)->{if(n==0)FeedTopics.sort(a,kind,sources);else if(n==1)FeedCatalog.browse(a,kind);else refreshAll(a,kind,sources);}).show()));
  tabs(a,kind,sources);TextView loading=a.text("Loading saved "+FeedCatalog.label(kind).toLowerCase(Locale.ROOT)+"…",14,MainActivity.MUTED,false);loading.setTag("feed-loading");a.body.addView(loading);a.miniPlayer();final FrameLayout page=a.mainFrame;if(a.navigation!=null)a.navigation.rememberFeed(kind,sources);
  loader.execute(()->{ArrayList<FeedStore.Feed> saved=FeedStore.load(a),selected=new ArrayList<>();for(FeedStore.Feed feed:saved)if(feed.kind.equals(kind)&&FeedTopics.source(a,feed))selected.add(feed);if(sources)FeedHighlights.sortSources(a,kind,selected);FeedStore.Feed combined=sources?null:FeedHighlights.combined(a,kind,saved);
   a.runOnUiThread(()->{if(a.isDestroyed()||a.isFinishing())return;Runnable render=()->{if(a.mainFrame!=page)return;a.body.removeAllViews();if(sources&&!selected.isEmpty())FeedList.attach(a,kind,selected,null);else if(!sources&&!combined.items.isEmpty()){if(kind.equals("Podcasts"))FeedList.attach(a,kind,null,combined);else FeedPosts.attach(a,combined);}else{a.body.addView(a.text(sources?"No sources in My list yet.":"No entries yet. Add or refresh sources to fill this tab.",16,MainActivity.MUTED,false));a.body.addView(a.button("Browse sources",()->FeedCatalog.browse(a,kind)));FeedRefresh.pullSources(a,kind);}a.miniPlayer();ScrollChrome.install(a);};if(a.mainFrame==page)render.run();else if(a.navigation!=null)a.navigation.defer(page,render);});
   FeedRefresh.maybe(a,kind);
  });
 }
 static void source(MainActivity a,FeedStore.Feed feed){a.body.addView(sourceView(a,feed));a.space(a.body,10);}
 static View sourceView(MainActivity a,FeedStore.Feed feed){LinearLayout row=a.row();row.setPadding(a.dp(14),a.dp(14),a.dp(14),a.dp(14));row.setBackground(UiStyle.surface(a,feed.kind,18));ImageView art=FeedIcons.tile(a,feed.title);row.addView(art,new LinearLayout.LayoutParams(a.dp(62),a.dp(62)));FeedArtwork.bindSource(a,art,feed);LinearLayout copy=a.column();TextView title=a.text(plain(feed.title),16,MainActivity.INK,true);title.setTypeface(a.serif,Typeface.BOLD);HindiTypography.apply(title,title.getText().toString());copy.addView(title);copy.addView(a.text(feed.items.size()+(feed.kind.equals("Podcasts")?" episodes":" articles")+(feed.error.isEmpty()?"":" · Refresh failed"),12,MainActivity.MUTED,false));if(!feed.items.isEmpty()){TextView latest=a.text(plain(feed.items.get(0).title),12,MainActivity.MUTED,false);latest.setMaxLines(2);copy.addView(latest);}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(14);row.addView(copy,cp);row.setContentDescription(feed.title);row.setOnClickListener(v->items(a,feed));row.setOnLongClickListener(v->{new AppDialog.Builder(a).setTitle(feed.kind.equals("Podcasts")?"Remove podcast?":"Remove from My list?").setMessage(feed.title).setPositiveButton("Remove",(d,n)->{FeedStore.remove(a,feed);show(a,feed.kind,true);}).setNegativeButton("Cancel",null).show();return true;});return row;}
 static void items(MainActivity a,FeedStore.Feed selected){FeedStore.Feed feed=selected;for(FeedStore.Feed current:FeedStore.load(a))if(current.kind.equals(selected.kind)&&current.url.equals(selected.url))feed=current;if(!feed.kind.equals("Podcasts")){FeedPosts.show(a,feed);return;}FeedStore.Feed shown=feed;a.screen=feed.kind+" feed";a.shell(feed.title);a.bar.getChildAt(0).setOnClickListener(v->show(a,shown.kind,true));a.bar.removeViewAt(2);a.bar.addView(UiStyle.icon(a,R.drawable.ic_browser_globe,"Browse "+feed.kind+" sources",()->FeedCatalog.browse(a,shown.kind),40));for(FeedStore.Item item:feed.items)entry(a,feed,item);if(feed.items.isEmpty())a.body.addView(a.text("No entries yet. Refresh this feed to check for updates.",14,MainActivity.MUTED,false));a.miniPlayer();for(int n=0;n<a.root.getChildCount();n++)if(a.root.getChildAt(n) instanceof ScrollView){FeedRefresh.pull(a,a.root.getChildAt(n),feed.kind,feed);break;}}
 static void refreshSource(MainActivity a,FeedStore.Feed feed){refresh(a,feed.kind,new ArrayList<>(Collections.singletonList(feed)));}
 static void add(MainActivity a,String kind){EditText input=new EditText(a);input.setSingleLine();input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);input.setHint("https://example.com/feed.xml");LinearLayout panel=a.column();panel.setPadding(a.dp(20),a.dp(8),a.dp(20),0);panel.addView(input);AlertDialog dialog=new AppDialog.Builder(a).setTitle("Add "+kind+" feed").setView(panel).setPositiveButton("Add",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String url=FeedStore.web(input.getText().toString());if(url.isEmpty()){input.setError("Enter a valid http or https RSS feed URL");return;}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);input.setEnabled(false);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setText("Loading…");a.io.execute(()->{try{FeedStore.Feed feed=FeedStore.download(url,kind);FeedStore.put(a,feed);a.runOnUiThread(()->{if(a.isDestroyed())return;dialog.dismiss();if(a.screen.equals(kind))show(a,kind);});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;input.setEnabled(true);input.setError(e.getMessage());dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setText("Add");});}});}));dialog.show();}
 static void manage(MainActivity a,String kind){ArrayList<FeedStore.Feed> feeds=new ArrayList<>();for(FeedStore.Feed f:FeedStore.load(a))if(f.kind.equals(kind))feeds.add(f);ArrayList<String> choices=new ArrayList<>();choices.add("Refresh all feeds");choices.add("Add RSS feed");for(FeedStore.Feed f:feeds)choices.add(f.title);new AppDialog.Builder(a).setTitle(kind+" feeds").setItems(choices.toArray(new String[0]),(d,n)->{if(n==0)refresh(a,kind,feeds);else if(n==1)add(a,kind);else{FeedStore.Feed f=feeds.get(n-2);new AppDialog.Builder(a).setTitle(f.title).setMessage(f.url+(f.error.isEmpty()?"":"\n\n"+f.error)).setPositiveButton("Refresh",(dd,x)->refresh(a,kind,new ArrayList<>(Collections.singletonList(f)))).setNeutralButton("Remove feed",(dd,x)->new AppDialog.Builder(a).setTitle("Remove feed?").setMessage("Remove this subscription and its cached entries? Your saved podcast playback positions are kept.").setPositiveButton("Remove",(ddd,y)->{FeedStore.remove(a,f);show(a,kind);}).setNegativeButton("Cancel",null).show()).setNegativeButton("Close",null).show();}}).setNegativeButton("Close",null).show();}
 static void refresh(MainActivity a,String kind,ArrayList<FeedStore.Feed> feeds){refresh(a,kind,feeds,a.feedSources);}
 static void refresh(MainActivity a,String kind,ArrayList<FeedStore.Feed> feeds,boolean sources){FeedRefresh.manual(a,kind,feeds);}
 static void entry(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){a.body.addView(entryView(a,feed,item));a.space(a.body,10);}
 static View entryView(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){LinearLayout row=a.row();row.setPadding(a.dp(14),a.dp(14),a.dp(14),a.dp(14));row.setBackground(UiStyle.surface(a,feed.kind,18));ImageView art=FeedIcons.tile(a,feed.title);row.addView(art,new LinearLayout.LayoutParams(a.dp(62),a.dp(62)));loadArt(a,art,item.image);LinearLayout copy=a.column();TextView title=a.text(plain(item.title),15,MainActivity.INK,true);title.setTypeface(a.serif,Typeface.BOLD);title.setMaxLines(2);copy.addView(title);String meta=item.date;if(a.screen.equals(feed.kind))meta=plain(feed.title)+(meta.isEmpty()?"":" · "+meta);if(feed.kind.equals("Podcasts")&&item.duration>0)meta=Store.time(item.duration)+(meta.isEmpty()?"":" · "+meta);TextView detail=a.text(meta,11,MainActivity.MUTED,false);detail.setMaxLines(1);copy.addView(detail);String description=feed.kind.equals("Podcasts")?EpisodeDescription.clean(item.description):plain(item.description);TextView summary=a.text(description,12,MainActivity.MUTED,false);summary.setMaxLines(2);summary.setEllipsize(TextUtils.TruncateAt.END);copy.addView(summary);
  if(feed.kind.equals("Podcasts")&&!description.isEmpty()){ImageButton more=UiStyle.icon(a,R.drawable.ic_episode_expand,"Expand episode description",()->{},36);final boolean[] expanded={false};more.setOnClickListener(v->{expanded[0]=!expanded[0];summary.setMaxLines(expanded[0]?Integer.MAX_VALUE:2);summary.setEllipsize(expanded[0]?null:TextUtils.TruncateAt.END);more.animate().rotation(expanded[0]?180f:0f).setDuration(140).start();more.setContentDescription(expanded[0]?"Collapse episode description":"Expand episode description");more.setSelected(expanded[0]);});LinearLayout footer=a.row();footer.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);footer.addView(more);copy.addView(footer,new LinearLayout.LayoutParams(-1,-2));}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(14);row.addView(copy,cp);row.setOnClickListener(v->{if(feed.kind.equals("Podcasts")&&!item.audio.isEmpty())play(a,feed,item);else article(a,feed,item);});row.setContentDescription(plain(item.title));return row;}
 static void loadArt(MainActivity a,ImageView image,String url){FeedArtwork.bind(a,image,url);}

 static void play(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){FeedHighlights.opened(a,item);ArrayList<Book> books=Store.load(a);Book target=null;for(Book b:books)if(b.uri.equals(item.audio)&&b.author.equals("Podcast"))target=b;if(target==null){target=new Book(item.audio,plain(item.title),"Podcast");target.duration=item.duration;target.chaptersChecked=true;books.add(target);}target.coverUri=item.image;Store.save(a,books);a.open(target);}
 static FeedStore.Item adjacent(MainActivity a,Book book,int direction){for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts")){ArrayList<FeedStore.Item> episodes=new ArrayList<>();for(FeedStore.Item item:feed.items)if(!item.audio.isEmpty())episodes.add(item);for(int i=0;i<episodes.size();i++)if(episodes.get(i).audio.equals(book.uri)){int at=i+direction;return at>=0&&at<episodes.size()?episodes.get(at):null;}}return null;}
 static boolean[] neighbours(MainActivity a,Book book){boolean[] found={false,false};for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts")){ArrayList<FeedStore.Item> episodes=new ArrayList<>();for(FeedStore.Item item:feed.items)if(!item.audio.isEmpty())episodes.add(item);for(int i=0;i<episodes.size();i++)if(episodes.get(i).audio.equals(book.uri)){found[0]=i>0;found[1]=i+1<episodes.size();return found;}}return found;}
 static void nextEpisode(MainActivity a,Book book,int direction){FeedStore.Item next=adjacent(a,book,direction);if(next==null)return;for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts"))for(FeedStore.Item item:feed.items)if(item.audio.equals(next.audio)){play(a,feed,item);return;}}
 static void article(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){FeedHighlights.opened(a,item);if(!item.link.isEmpty()){a.startActivity(new Intent(a,ArticleActivity.class).putExtra("url",item.link).putExtra("title",plain(item.title)).putExtra("summary",item.description).putExtra("image",item.image));return;}a.screen=feed.kind+" article";a.shell(feed.kind);a.bar.getChildAt(0).setOnClickListener(v->show(a,feed.kind));TextView title=a.text(plain(item.title),25,MainActivity.INK,true);a.body.addView(title);a.space(a.body,10);a.body.addView(a.text(feed.title+" · "+item.date,12,MainActivity.MUTED,false));if(!item.image.isEmpty()){ImageView art=new ImageView(a);art.setScaleType(ImageView.ScaleType.FIT_CENTER);a.body.addView(art,new LinearLayout.LayoutParams(-1,a.dp(180)));loadArt(a,art,item.image);}a.space(a.body,14);TextView text=a.text(plain(item.description),18,MainActivity.INK,false);text.setLineSpacing(a.dp(5),1.1f);text.setTextIsSelectable(true);a.body.addView(text);if(item.description.isEmpty())a.body.addView(a.text("This feed does not include article text. Open the source to read it.",14,MainActivity.MUTED,false));a.space(a.body,20);if(!item.link.isEmpty())a.body.addView(a.button("Read on website",()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(item.link)))));if(!item.document.isEmpty())a.body.addView(a.button("Open attached PDF",()->openPdf(a,item.document,item.title)));}
 static void openPdf(MainActivity a,String url,String title){ProgressDialog wait=new ProgressDialog(a);wait.setMessage("Opening PDF…");wait.setCancelable(false);wait.show();a.io.execute(()->{try{byte[] bytes=FeedStore.fetch(url,64*1024*1024);java.io.File file=java.io.File.createTempFile("journal-",".pdf",a.getCacheDir());try(java.io.OutputStream out=new java.io.FileOutputStream(file)){out.write(bytes);}a.runOnUiThread(()->{if(a.isDestroyed())return;wait.dismiss();a.startActivity(new Intent(a,ReaderActivity.class).putExtra("uri",Uri.fromFile(file).toString()).putExtra("kind","PDF").putExtra("title",plain(title)));});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;wait.dismiss();new AppDialog.Builder(a).setTitle("PDF attachment").setMessage(e.getMessage()).setPositiveButton("Close",null).show();});}});}
}
